    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return s
    if isinstance(v, float):
        return int(v) if v.is_integer() else v
    return v

def to_serial(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return (v - EPOCH).total_seconds() / 86400.0
    if isinstance(v, date):
        return (datetime(v.year, v.month, v.day) - EPOCH).total_seconds() / 86400.0
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            pass
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y"):
            try:
                return (datetime.strptime(s, fmt) - EPOCH).total_seconds() / 86400.0
            except ValueError:
                pass
    return None

a2 = norm_key(vws["A2"].value)
q_col = column_index_from_string("Q")
u_col = column_index_from_string("U")
y_col = column_index_from_string("Y")

match_row = None
for r in range(2, vws.max_row + 1):
    qv = vws.cell(row=r, column=q_col).value
    if a2 is not None and norm_key(qv) == a2:
        match_row = r
        break

result = None
if match_row is not None:
    u_raw = vws.cell(row=match_row, column=u_col).value
    y_raw = vws.cell(row=match_row, column=y_col).value
    u = to_serial(u_raw)
    y = to_serial(y_raw)
    if u is not None and y is not None:
        result = round(y - u, 2)
        if result == int(result):
            result = int(result)

ws["C2"] = result
wb.save(OUT)

print("active:", active_name)
print("A2:", a2)
print("match_row:", match_row)
if match_row is not None:
    print("U:", vws.cell(row=match_row, column=u_col).value)
    print("Y:", vws.cell(row=match_row, column=y_col).value)
print("C2:", result)
